using System.Text;using System.Text.Json;using System.Text.RegularExpressions;
namespace UnifiedMediaHub.Core;

public sealed record BridgeImportResult(string JobId,int ItemCount);
public sealed record BridgePayload(JsonElement Value,string ListKind,string? ViewerId,string ViewerName,int Count,string? FolderTitle=null)
{
 public const int MaxBytes=8*1024*1024;
 static readonly Regex Id=new("^[A-Za-z0-9_-]{1,200}$",RegexOptions.CultureInvariant);
 static void Keys(JsonElement element,params string[] allowed){if(element.ValueKind!=JsonValueKind.Object)throw new InvalidDataException();var seen=new HashSet<string>();foreach(var p in element.EnumerateObject())if(!allowed.Contains(p.Name)||!seen.Add(p.Name))throw new InvalidDataException();}
 static string Text(JsonElement value,string key,int max,bool required=true){if(!value.TryGetProperty(key,out var p)){if(required)throw new InvalidDataException();return "";}if(p.ValueKind!=JsonValueKind.String||p.GetString() is not {} s||s.Length>max||s.Any(char.IsControl))throw new InvalidDataException();return s;}
 public static BridgePayload Parse(ReadOnlyMemory<byte> bytes){if(bytes.Length>MaxBytes)throw new InvalidDataException();using var doc=JsonDocument.Parse(bytes,new(){MaxDepth=64});var root=doc.RootElement;Keys(root,"bridgeVersion","platform","listKind","page","viewer","owner","items","folder");if(Text(root,"bridgeVersion",1)!="1"||Text(root,"platform",20)!="douyin")throw new InvalidDataException();var kind=Text(root,"listKind",12);if(kind is not("liked" or "saved" or "profile" or "saved_folder"))throw new InvalidDataException();var page=root.GetProperty("page");Keys(page,"path","tab");var path=Text(page,"path",220);if(!Regex.IsMatch(path,"^/user/[A-Za-z0-9_-]{1,200}/?$",RegexOptions.CultureInvariant)||Text(page,"tab",32)!=(kind=="liked"?"like":kind=="saved"?"favorite_collection":kind=="saved_folder"?"favorite_folder":"post"))throw new InvalidDataException();string? viewer=null;var nickname="身份未提供";foreach(var key in new[]{"viewer","owner"})if(root.TryGetProperty(key,out var person)){Keys(person,"secUid","nickname","uniqueId");var id=Text(person,"secUid",200);if(!Id.IsMatch(id))throw new InvalidDataException();var name=Text(person,"nickname",200,false);_=Text(person,"uniqueId",200,false);if(key=="viewer"){viewer=id;nickname=string.IsNullOrWhiteSpace(name)?"昵称未提供":name;}}
  // One opened 收藏夹 (saved_folder) may carry its name; a name on any other list is rejected.
  string? folderTitle=null;if(root.TryGetProperty("folder",out var folder)){if(kind!="saved_folder")throw new InvalidDataException();Keys(folder,"title","id");folderTitle=Text(folder,"title",256).Trim();if(folderTitle.Length==0)throw new InvalidDataException();var folderId=Text(folder,"id",24,false);if(folderId.Length>0&&!Regex.IsMatch(folderId,"^[0-9]{1,24}$",RegexOptions.CultureInvariant))throw new InvalidDataException();}
  var items=root.GetProperty("items");if(items.ValueKind!=JsonValueKind.Array||items.GetArrayLength() is <1 or >1000)throw new InvalidDataException();var ids=new HashSet<string>();foreach(var item in items.EnumerateArray()){Keys(item,"hrefId","aweme","oversized");var href=Text(item,"hrefId",32);if(!Regex.IsMatch(href,"^[0-9]{1,32}$",RegexOptions.CultureInvariant)||!ids.Add(href))throw new InvalidDataException();if(item.TryGetProperty("oversized",out var oversized)){if(oversized.ValueKind!=JsonValueKind.True||item.TryGetProperty("aweme",out _))throw new InvalidDataException();continue;}var aweme=item.GetProperty("aweme");if(aweme.ValueKind!=JsonValueKind.Object||Encoding.UTF8.GetByteCount(aweme.GetRawText())>256*1024)throw new InvalidDataException();}
  return new(root.Clone(),kind,viewer,nickname,items.GetArrayLength(),folderTitle);
 }
}
